from types import SimpleNamespace

import cv2
import numpy as np
import pytest

from orchestrator import assets
from tests.waiting import HANG_S, until

REPO = Path(__file__).resolve().parents[2]


@pytest.fixture()
def synthetic_manifest(tmp_path):
    """Manifest metadata for generated bytes, never a biological or simulation fixture."""
    data = b"synthetic recording sentinel"
    source = tmp_path / "generated.mp4"
    source.write_bytes(data)
    return {"backup": {}, "real": [{
        "id": "2026-10-13-synthetic-1s", "file": "footage/real/2026-10-13-synthetic-1s.mp4",
        "sha256": assets.sha256(source), "bytes": len(data), "seconds": 1.0,
        "title": "Synthetic asset metadata", "specimen": "generated bytes", "date": "2026-10-13",
        "microscope": False, "optics": dict.fromkeys(assets.OPTICS_FIELDS),
    }], "bench": [{"path": "bench/synthetic", "what": "generated test bytes", "rebuild": "pytest fixture"}]}


def video(path: Path, frames: int = 15) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    writer = cv2.VideoWriter(str(path), cv2.VideoWriter_fourcc(*"mp4v"), 30, (64, 48))
    for i in range(frames):
        writer.write(np.full((48, 64, 3), i * 10 % 255, np.uint8))
    writer.release()
    return path


def test_the_store_is_one_folder_outside_the_checkout_moved_by_one_variable(tmp_path):
    s = assets.Store.from_env({"MICROMIND_ASSETS": str(tmp_path)})
    assert (s.real, s.corpus_footage, s.corpus_sources, s.bench("naming")) == (
        tmp_path / "footage" / "real", tmp_path / "footage" / "corpus", tmp_path / "sources" / "corpus", tmp_path / "bench" / "naming")
    assert assets.Store.from_env({}).root == Path.home() / "MicroscopeMind"


@pytest.mark.parametrize("backup", [{}, {"backup": None}, {"backup": {}}])
@pytest.mark.parametrize("remote", [False, True])
def test_empty_local_manifest_status_needs_no_backup_or_network(tmp_path, monkeypatch, capsys, remote, backup):
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps({**backup, "real": [], "bench": []}))
    monkeypatch.setattr(assets, "MANIFEST", manifest)
    monkeypatch.setenv("MICROMIND_ASSETS", str(tmp_path / "store"))
    monkeypatch.setattr(assets, "subprocess", SimpleNamespace(
        run=lambda *a, **kw: pytest.fail("local asset status contacted a process")))

    assert assets.main(["status", *(["--remote"] if remote else [])]) == 0
    output = capsys.readouterr().out
    assert "No backup destination configured" in output
    assert "No real recordings listed" in output
    assert "backed up to" not in output


@pytest.mark.parametrize("backup", [{}, {"backup": None}, {"backup": {}}])
@pytest.mark.parametrize("command", ["fetch", "backup"])
def test_empty_local_manifest_has_nothing_to_transfer(tmp_path, monkeypatch, capsys, command, backup):
    manifest = tmp_path / "manifest.json"
