@pytest.mark.parametrize("command", ["status", "fetch", "backup"])
@pytest.mark.parametrize("present", [False, True])
def test_local_recordings_without_a_backup_are_never_sent_elsewhere(
        tmp_path, monkeypatch, capsys, synthetic_manifest, command, present):
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps(synthetic_manifest))
    monkeypatch.setattr(assets, "MANIFEST", manifest)
    monkeypatch.setenv("MICROMIND_ASSETS", str(tmp_path / "store"))
    local = assets.store().real_file("2026-10-13-synthetic-1s")
    if present:
        local.parent.mkdir(parents=True)
        local.write_bytes(b"synthetic recording sentinel")
    monkeypatch.setattr(assets, "subprocess", SimpleNamespace(
        run=lambda *a, **kw: pytest.fail("no backup destination was configured")))

    assert assets.main([command]) == (0 if present and command == "fetch" else 1)
    output = capsys.readouterr().out
    if present and command == "fetch":
        assert "All listed recordings are present" in output
    else:
        assert "No backup destination configured" in output
        if command == "status":
            assert "NO BACKUP CONFIGURED" in output
            assert ("ok" if present else "missing") in output
    assert local.exists() == present
    if present:
        assert local.read_bytes() == b"synthetic recording sentinel"


@pytest.mark.parametrize("source", ["checkout", "synthetic"])
def test_the_manifest_lists_every_real_recording_once_with_what_brings_it_back(synthetic_manifest, source):
    # Keep the nonempty structure checked even in a public checkout with no private metadata.
    manifest = assets.load_manifest() if source == "checkout" else {
        **synthetic_manifest, "backup": {"kind": "github-release", "repo": "example/synthetic-assets", "tag": "fixtures"}}
    assert isinstance(manifest["real"], list) and isinstance(manifest["bench"], list)
    backup = manifest.get("backup")
    assert backup is None or isinstance(backup, dict)
    if backup:
        assert backup["kind"] == "github-release"
        assert re.fullmatch(r"[^/\s]+/[^/\s]+", backup["repo"])
        assert isinstance(backup["tag"], str) and backup["tag"].strip()
    ids = [r["id"] for r in manifest["real"]]
    assert len(ids) == len(set(ids)) and ids == sorted(ids)
    for r in manifest["real"]:
        path = Path(r["file"])
        assert path.parent == Path("footage/real") and path.stem == r["id"] and path.suffix in assets.VIDEO_SUFFIXES
        assert re.fullmatch(r"[0-9a-f]{64}", r["sha256"]) and r["bytes"] > 0 and r["seconds"] > 0
        assert r["title"] and r["specimen"] and re.fullmatch(r"\d{4}-\d{2}-\d{2}", r["date"]) and r["id"].startswith(r["date"])
        assert isinstance(r["microscope"], bool)
        assert set(r["optics"]) == set(assets.OPTICS_FIELDS)  # what it was filmed with: every field, null if unknown
    for bench in manifest["bench"]:
        path = Path(bench["path"])
        assert path.is_relative_to("bench") and ".." not in path.parts
        assert bench["what"] and bench["rebuild"]


