def test_status_counts_each_corpus_items_own_tours(tmp_path, monkeypatch):
    corpus = tmp_path / "corpus.json"
    corpus.write_text(json.dumps({"items": [{"id": "pond", "specimen": "pond"}, {"id": "pond-seah", "specimen": "pond (Seah)"},
                                            {"id": "nih", "specimen": "smear", "fetch": {"kind": "manual", "how": "by hand"}}]}))
