def test_add_copies_a_recording_in_with_its_checksum_and_never_twice(tmp_path, monkeypatch, capsys):
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps({"backup": {}, "real": [], "bench": []}))
    monkeypatch.setattr(assets, "MANIFEST", manifest)
    monkeypatch.setenv("MICROMIND_ASSETS", str(tmp_path / "store"))
    source = video(tmp_path / "capture.mp4", frames=45)
    args = SimpleNamespace(file=str(source), specimen="Onion epidermis", title=None, date="2026-10-07", notes="", not_microscope=False)
    assert assets.cmd_add(args) == 0
    assert "No backup destination configured" in capsys.readouterr().out
    (entry,) = json.loads(manifest.read_text())["real"]
    assert entry["id"] == "2026-10-07-onion-epidermis-2s" and entry["file"] == "footage/real/2026-10-07-onion-epidermis-2s.mp4"
    copied = tmp_path / "store" / entry["file"]
    assert copied.read_bytes() == source.read_bytes() and entry["sha256"] == assets.sha256(copied) and entry["microscope"]
    assert assets.real_status(assets.store(), entry, verify=True) == "ok"
    assert assets.cmd_add(args) == 1  # the same recording is not added twice
    copied.write_bytes(b"changed")
    assert assets.real_status(assets.store(), entry) == "changed"


def test_migrate_moves_an_old_checkouts_footage_and_bench_data_and_leaves_links(tmp_path, monkeypatch):
    checkout = tmp_path / "checkout"
    video(checkout / "footage" / "corpus-bccd.mp4", frames=2)
    (checkout / "footage" / "corpus-bccd.truth.json").write_text("{}")
    video(checkout / "footage" / "mine.mp4", frames=2)
    (checkout / "footage" / "README.md").write_text("kept")
    (checkout / "footage" / "leaf.mp4").symlink_to(checkout / "footage" / "mine.mp4")
    (checkout / "footage" / "corpus" / "raw" / "bccd").mkdir(parents=True)
    (checkout / "services" / "bench" / "data" / "naming").mkdir(parents=True)
    (checkout / "services" / "bench" / "frames").mkdir(parents=True)
    store = tmp_path / "store"
    monkeypatch.setenv("MICROMIND_ASSETS", str(store))
    assert assets.cmd_migrate(SimpleNamespace(source=str(checkout), dry_run=False)) == 0
    assert (store / "footage" / "corpus" / "corpus-bccd.mp4").exists() and (store / "footage" / "corpus" / "corpus-bccd.truth.json").exists()
    assert (store / "footage" / "mine.mp4").exists() and (store / "sources" / "corpus" / "bccd").is_dir()
    assert (store / "bench" / "naming").is_dir() and (store / "bench" / "frames").is_dir()
    assert (checkout / "footage" / "README.md").exists() and (checkout / "footage" / "leaf.mp4").is_symlink()
    assert not (checkout / "footage" / "corpus-bccd.mp4").exists()


