@pytest.mark.parametrize('kind', ['still', 'recording', 'short-recording'])
def test_thumbnail_threads_are_bounded_without_changing_output(bridge, tmp_path, monkeypatch, kind):
    """A serialized job must also bound ffmpeg's internal pools; preserve pixels and seek fallback."""
    import subprocess
    import footage_media

    source = tmp_path / ('input.png' if kind == 'still' else 'input.mp4')
    if kind == 'still':
        cv2.imwrite(str(source), np.random.default_rng(3).integers(0, 256, (48, 64, 3), dtype=np.uint8))
    else:
        video(source, frames=45)
    library = footage_media.Library.__new__(footage_media.Library)
    library.path = lambda _: source
    run = subprocess.run
    calls = []
    output = tmp_path / 'thumb.jpg'

    def capture(cmd, **kwargs):
        if cmd[-1] == str(output.with_suffix('.tmp.jpg')):
            calls.append(list(cmd))
        return run(cmd, **kwargs)

    monkeypatch.setattr(footage_media.subprocess, 'run', capture)
    item = {'kind': 'still' if kind == 'still' else 'recording',
            'seconds': 100 if kind == 'short-recording' else 1.5}
    library._make_thumb(item, output)
    assert output.is_file() and cv2.imread(str(output)).shape == (180, 240, 3)
    assert len(calls) == (2 if kind == 'short-recording' else 1)
    for cmd in calls:
        input_at = cmd.index('-i')
        thread_positions = [i for i, word in enumerate(cmd) if word == '-threads']
        assert len(thread_positions) == 2, 'decoder and encoder pools both need explicit bounds'
        assert thread_positions[0] < input_at < thread_positions[1]
        assert all(cmd[i + 1] == '1' for i in thread_positions)
        assert cmd[cmd.index('-filter_threads') + 1] == '1'
    # Same upstream command without thread bounds is the reference for image content.
    unbounded, skip = [], False
    for word in calls[-1]:
        if skip:
            skip = False
        elif word in ('-threads', '-filter_threads'):
            skip = True
        else:
            unbounded.append(word)
    unbounded[-1] = str(tmp_path / 'reference.jpg')
    assert run(unbounded, capture_output=True, timeout=60).returncode == 0
    assert output.read_bytes() == Path(unbounded[-1]).read_bytes()
    library._make_thumb(item, output)
    assert len(calls) == (2 if kind == 'short-recording' else 1), 'retained thumbnails need no process'


def test_a_paced_worker_follows_the_machine_and_holds_prefetch_when_told(bridge):
    """--media-pace follow (L1c): as many jobs at once as the pace allows; with a pace of 0 for prefetch, only the
    job someone waits for runs, and the prefetch waits until the pace allows it again."""
    import threading

    from footage_media import Worker

    allowed = {"requested": 3, "prefetch": 3}
    worker = Worker(pace=lambda requested: allowed["requested" if requested else "prefetch"])
    running, most, release = [0], [0], threading.Event()
    lock = threading.Lock()

    def job():
        with lock:
            running[0] += 1
            most[0] = max(most[0], running[0])
        release.wait(HANG_S)
        with lock:
            running[0] -= 1

    events = [worker.submit(f"j{n}", job) for n in range(5)]
    until(lambda: running[0] == 3, what="three jobs side by side")
    release.set()
    for event in events:
        assert event.wait(HANG_S)
    assert most[0] == 3

    allowed.update(requested=1, prefetch=0)  # the bridge lost its frame rate
    order: list[str] = []
    held = worker.submit("prefetch", lambda: order.append("prefetch"))
    asked = worker.submit("asked", lambda: order.append("asked"), requested=True)
    assert asked.wait(HANG_S) and not held.wait(0.5) and order == ["asked"]
    allowed["prefetch"] = 1  # the frame rate is back
    assert held.wait(HANG_S) and order == ["asked", "prefetch"]


def test_a_failing_pace_is_one_job_at_a_time(bridge):
    from footage_media import Worker

    worker = Worker(pace=lambda requested: 1 / 0)
    assert worker._allowed(True) == 1 and worker._allowed(False) == 1


def test_work_in_the_background_returns_its_answer_or_its_error_on_a_thread_of_its_own(bridge):
    """--upload-priority background (L1c): the copy runs on a thread made for it, lowered to background priority on
    macOS (a lowered thread cannot raise itself again, so never the request thread), and its answer or its error
    comes back to the caller."""
    import ctypes
    import sys
    import threading

    from footage_media import QOS_CLASS_BACKGROUND, in_background

    seen = {}

    def work():
        seen["thread"] = threading.current_thread()
        if sys.platform == "darwin":
            system = ctypes.CDLL("/usr/lib/libSystem.B.dylib")
            system.qos_class_self.restype = ctypes.c_uint
            seen["qos"] = system.qos_class_self()
        return 42

    assert in_background(work) == 42
    assert seen["thread"] is not threading.current_thread()
    if sys.platform == "darwin":
        assert seen["qos"] == QOS_CLASS_BACKGROUND
    with pytest.raises(ValueError, match="does not play"):
        in_background(lambda: (_ for _ in ()).throw(ValueError("That file does not play as a video")))


def test_an_upload_in_the_background_is_added_as_before(bridge, tmp_path):
    import io

    from footage_media import Library, in_background

    footage = tmp_path / "footage"
    footage.mkdir()
    library = Library(footage, tmp_path / "none.json", tmp_path / "none.json")
    data = video(tmp_path / "phone.mp4", frames=45).read_bytes()
    item = in_background(lambda: library.receive(io.BytesIO(data), len(data), "clip.mp4", "", "Onion epidermis", True))
    assert item["group"] == "Added here" and (footage / item["name"]).read_bytes() == data
    with pytest.raises(ValueError):
        in_background(lambda: library.receive(io.BytesIO(b"not a video"), 11, "notes.mp4", "", "x", True))
